// Deterministic Task Intake Validation & Secret Scrubbing
const body = $input.item.json.body || $input.item.json;

// 1. Mandatory field checks
if (!body.taskId || !body.userObjective || !body.repository || !body.targetCommit) {
  return [{
    json: {
      status: 'BLOCKED',
      error: 'Missing mandatory fields: taskId, userObjective, repository, targetCommit',
      taskId: body.taskId || 'UNKNOWN',
      timestamp: new Date().toISOString()
    }
  }];
}

// 2. Prompt injection guard
const injectionRegex = /(ignore all rules|bypass authorization|grant root permissions)/i;
if (injectionRegex.test(body.userObjective)) {
  return [{
    json: {
      status: 'BLOCKED',
      error: 'SECURITY_ALERT: Prompt injection detected in userObjective',
      taskId: body.taskId,
      timestamp: new Date().toISOString()
    }
  }];
}

// 3. Deterministic classification
const obj = body.userObjective.toLowerCase();
let classification = 'AUDIT_ONLY';
if (obj.includes('test') || obj.includes('benchmark')) classification = 'TEST_ONLY';
else if (obj.includes('security') || obj.includes('secret')) classification = 'SECURITY_REVIEW';
else if (obj.includes('document')) classification = 'DOCUMENTATION';
else if (obj.includes('implement') || obj.includes('build')) {
  // Must have human authorization
  if (body.authorizedBy && body.authorizedBy !== 'LLM') classification = 'IMPLEMENTATION';
  else classification = 'AUDIT_ONLY';
}

return [{
  json: {
    status: 'VALIDATED',
    taskId: body.taskId,
    correlationId: body.correlationId || 'CORR-' + Date.now(),
    classification: classification,
    userObjective: body.userObjective,
    repository: body.repository,
    targetCommit: body.targetCommit,
    allowedScope: body.allowedScope || [],
    timestamp: new Date().toISOString()
  }
}];
